SELECT CASE WHEN duration_sec >= 424 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec, SUM(CASE WHEN event_type = 'click' THEN duration_sec ELSE 0 END) AS click_duration_sec, STDDEV_SAMP(duration_sec) AS duration_sec_stddev FROM web_events GROUP BY duration_sec_tier HAVING cart_duration_sec > 0 ORDER BY cart_duration_sec DESC;
